class Solution {
public:
    vector<int> amountPainted(vector<vector<int>>& paint) {
        vector<int> jump(50005, 0);
        function<int(int)> find = [&](int x) {
            return jump[x] == 0 ? x : jump[x] = find(jump[x]);
        };
        vector<int> ans;
        for (auto& p : paint) {
            int start = p[0], end = p[1];
            int work = 0;
            int cur = start;
            while (cur < end) {
                int nextCur = find(cur);
                if (nextCur >= end) break;
                work++;
                jump[nextCur] = find(nextCur + 1);
                cur = jump[nextCur];
            }
            ans.push_back(work);
        }
        return ans;
    }
};

class Solution {
    int[] jump = new int[50005];
    int find(int x) {
        return jump[x] == 0 ? x : (jump[x] = find(jump[x]));
    }
    public int[] amountPainted(int[][] paint) {
        int n = paint.length;
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            int start = paint[i][0], end = paint[i][1];
            int work = 0;
            int cur = start;
            while (cur < end) {
                int nextCur = find(cur);
                if (nextCur >= end) break;
                work++;
                jump[nextCur] = find(nextCur + 1);
                cur = jump[nextCur];
            }
            ans[i] = work;
        }
        return ans;
    }
}

